mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("hit -> cog via [hot,dot,dog,lot,log,cog]","5"),
        ("hit -> hot via [hot]","2"),
        ("cat -> dog via [cot,cog,dog]","4"),
        ("hit -> cog via [hot,dot]","0"),
        ("aaa -> bbb via [aab,abb,bbb]","4"),
        ("  \nhit -> cog via [hot,dot,dog,lot,log,cog]\n  ","5"),
        ("\naaa -> bbb via [aab,abb,bbb]\n","4")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS bidirectional-bfs");
}
